SELECT * FROM customer limit 20;

--Q.1 What is the total revenue generated by male vs. female customers?
SELECT 
	gender,
	SUM(purchase_amount) AS total_revenue
FROM customer
GROUP BY gender
ORDER BY total_revenue DESC;

--Q.2 Which customers used a discount but still spent more than the average purchase amount?
SELECT 
	customer_id,
	purchase_amount
FROM customer
WHERE discount_applied = 'Yes' 
AND 
purchase_amount > (
SELECT 
	AVG(purchase_amount)
FROM customer
);

--Q.3 Which are the top 5 products with the highest average review rating?
SELECT 
	item_purchased,
	ROUND(AVG(review_rating::numeric),2) avg_product_rating
FROM customer
GROUP BY item_purchased
ORDER BY avg_product_rating DESC
LIMIT 5;

--Q.4 Compare the average purchase amount between Standard and Express Shipping.
SELECT 
	shipping_type,
	ROUND(AVG(purchase_amount),2) AS avd_purchase_amount
FROM customer
WHERE shipping_type IN ('Standard','Express')
GROUP BY shipping_type;

--Q.5 Do subscribed customers spend more ? 
--    Compare average spend and total revenue between sobscribers and non-subscibers.
SELECT 
	subscription_status,
	COUNT(customer_id) AS total_customers,
	ROUND(AVG(purchase_amount),2) AS avg_spend,
	SUM(purchase_amount) AS total_revenue
FROM customer
GROUP BY subscription_status
ORDER BY total_revenue, avg_spend DESC;

--Q.6 Which 5 products have the highest percentage of purchases with discounts applied?
SELECT 
	item_purchased,
	ROUND(100 * SUM(CASE 
				WHEN discount_applied = 'Yes' THEN 1 
				ELSE 0
			   END
			  ) / COUNT(*),2) AS discount_rate
FROM customer
GROUP BY item_purchased
ORDER BY discount_rate DESC
LIMIT 5;

--Q.7 Segment customers into New, Returning and Loyal based on their total number of previous purchases,
--    and show the count of each segment.
WITH customer_type AS ( 
	SELECT 	
		customer_id,
		previous_purchases,
		CASE 
			WHEN previous_purchases = 1 THEN 'New'
			WHEN previous_purchases BETWEEN 2 AND 10 THEN 'Returning'
			ELSE 'Loyal'
		END AS customer_segment
	FROM customer
)
SELECT 
	customer_segment,
	COUNT(*) AS total_customers
FROM customer_type
GROUP BY customer_segment;

--Q.8 What are the top 3 most purchased products from each category?
WITH item_count AS
(
	SELECT 
		category,
		item_purchased,
		COUNT(*) AS Total_orders,
		ROW_NUMBER() OVER(PARTITION BY category ORDER BY COUNT(*) DESC) product_rank
	FROM customer
	GROUP BY 
		category,
		item_purchased
)
SELECT 
	product_rank,
	category,
	item_purchased,
	Total_orders
FROM item_count
WHERE product_rank <= 3;

--Q.9 Are customers who are repeat buyers (more than 5 previous purchases) also likely to subscribe?
SELECT 
	subscription_status,
	COUNT(*) AS repeat_customers
FROM customer
WHERE previous_purchases > 5
GROUP BY subscription_status;

--Q.10 What is the revenue contribution of each age group?
SELECT 
	age_group,
	SUM(purchase_amount) AS revenue
FROM customer
GROUP BY age_group
ORDER BY revenue DESC;

